preset_css:
/* RPG Inject */
.mor-post, .runelite-panel { border: 2px solid #5a4a35; border-radius: 4px; box-shadow: inset 0 0 10px rgba(0,0,0,0.8), 0 4px 6px rgba(0,0,0,0.5); }
.panel-header { background: #2a2218; border-bottom: 2px solid #19140d; }
h1, h2, h3, a { text-shadow: 1px 1px 0px #000000; }
button, .pager-btn { background: #601818 !important; border: 1px solid #8a2020 !important; color: #ffcc00 !important; box-shadow: inset 0 1px 0 #a33, 0 1px 2px #000; text-shadow: 1px 1px 0 #000; }
button:hover, .pager-btn:hover { background: #7a1f1f !important; }
